package com.beeboee.magnot.network;import com.beeboee.magnot.Magnot;import com.beeboee.magnot.client.ClientRegionStore;import com.beeboee.magnot.region.*;import com.beeboee.magnot.server.RegionActions;import net.minecraft.network.PacketBuffer;import net.minecraft.util.ResourceLocation;import net.minecraft.util.math.BlockPos;import net.minecraft.world.server.ServerWorld;import net.minecraft.entity.player.ServerPlayerEntity;import net.minecraftforge.fml.network.*;import net.minecraftforge.fml.network.simple.SimpleChannel;import java.util.*;import java.util.function.Supplier;public final class MagnotNetwork{private static final String V="2";private static final SimpleChannel C=NetworkRegistry.newSimpleChannel(new ResourceLocation(Magnot.MOD_ID,"main"),()->V,V::equals,V::equals);private static int id;private MagnotNetwork(){}public static void register(){C.registerMessage(id++,Sync.class,Sync::encode,Sync::decode,Sync::handle,Optional.of(NetworkDirection.PLAY_TO_CLIENT));C.registerMessage(id++,Remove.class,Remove::encode,Remove::decode,Remove::handle,Optional.of(NetworkDirection.PLAY_TO_SERVER));}public static void sync(ServerPlayerEntity p){if(p.level instanceof ServerWorld)C.send(PacketDistributor.PLAYER.with(()->p),new Sync(FerrousRegionSavedData.get((ServerWorld)p.level).regions()));}public static void syncDimension(ServerWorld l){C.send(PacketDistributor.DIMENSION.with(l::dimension),new Sync(FerrousRegionSavedData.get(l).regions()));}public static void remove(UUID u){C.sendToServer(new Remove(u));}public static final class Sync{final List<FerrousRegion> rs;Sync(List<FerrousRegion>rs){this.rs=new ArrayList<FerrousRegion>(rs);}static void encode(Sync p,PacketBuffer b){b.writeVarInt(p.rs.size());for(FerrousRegion r:p.rs){b.writeUUID(r.id());b.writeUUID(r.groupId());b.writeBlockPos(r.min());b.writeBlockPos(r.max());}}static Sync decode(PacketBuffer b){int n=b.readVarInt();List<FerrousRegion>rs=new ArrayList<FerrousRegion>();for(int i=0;i<n;i++)rs.add(new FerrousRegion(b.readUUID(),b.readUUID(),b.readBlockPos(),b.readBlockPos()));return new Sync(rs);}static void handle(Sync p,Supplier<NetworkEvent.Context> c){c.get().enqueueWork(()->ClientRegionStore.set(p.rs));c.get().setPacketHandled(true);}}public static final class Remove{final UUID id;Remove(UUID id){this.id=id;}static void encode(Remove p,PacketBuffer b){b.writeUUID(p.id);}static Remove decode(PacketBuffer b){return new Remove(b.readUUID());}static void handle(Remove p,Supplier<NetworkEvent.Context> c){ServerPlayerEntity player=c.get().getSender();if(player!=null)c.get().enqueueWork(()->RegionActions.remove(player,p.id));c.get().setPacketHandled(true);}}}
